module APBSPI(
  input         clock,
                reset,
                auto_apply_in_psel,
                auto_apply_in_penable,
                auto_apply_in_pwrite,
  input  [29:0] auto_apply_in_paddr,
  input  [31:0] auto_apply_in_pwdata,
  input  [3:0]  auto_apply_in_pstrb,
  output        auto_apply_in_pready,
                auto_apply_in_pslverr,
  output [31:0] auto_apply_in_prdata,
  output        extra_sck,
                extra_ss,
                extra_mosi,
  input         extra_miso
);

  wire        __in_pready;
  wire [31:0] __in_prdata;
  wire [7:0]  __spi_ss;
  wire        __spi_irq_out;
  reg  [3:0]  _GEN;
  reg  [1:0]  _GEN_0;
  wire        _GEN_1 = _GEN_0 == 2'h2;
  wire        _GEN_2 = _GEN_1 & __in_pready;
  wire        _GEN_3 = _GEN == 4'h1;
  wire        _GEN_4 = _GEN == 4'h2;
  wire        _GEN_5 = _GEN == 4'h3;
  wire        _GEN_6 = _GEN == 4'h4;
  wire        _GEN_7 = _GEN == 4'h5;
  wire        _GEN_8 = _GEN == 4'h6;
  wire        _GEN_9 = _GEN == 4'h8;
  wire        _GEN_10 = _GEN_0 == 2'h1;
  always @(posedge clock) begin
    if (reset) begin
      _GEN <= 4'h0;
      _GEN_0 <= 2'h0;
    end
    else begin
      if (|_GEN) begin
        if (_GEN_3) begin
          if (_GEN_2)
            _GEN <= 4'h0;
        end
        else if (_GEN_4) begin
          if (_GEN_2)
            _GEN <= 4'h3;
        end
        else if (_GEN_5) begin
          if (_GEN_2)
            _GEN <= 4'h4;
        end
        else if (_GEN_6) begin
          if (_GEN_2)
            _GEN <= 4'h5;
        end
        else if (_GEN_7) begin
          if (_GEN_2)
            _GEN <= 4'h6;
        end
        else if (_GEN_8) begin
          if (_GEN_2)
            _GEN <= 4'h7;
        end
        else if (_GEN == 4'h7) begin
          if (__spi_irq_out)
            _GEN <= 4'h8;
        end
        else if (_GEN_9 & _GEN_2)
          _GEN <= 4'h0;
      end
      else if (auto_apply_in_psel & auto_apply_in_penable)
        _GEN <= auto_apply_in_paddr > 30'h2FFFFFFF & ~auto_apply_in_pwrite ? 4'h2 : 4'h1;
      if (_GEN_0 == 2'h0) begin
        if ((|_GEN) & _GEN != 4'h7)
          _GEN_0 <= 2'h1;
      end
      else if (_GEN_10)
        _GEN_0 <= 2'h2;
      else if (_GEN_2)
        _GEN_0 <= 2'h0;
    end
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:0];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        _RANDOM[/*Zero width*/ 1'b0] = `RANDOM;
        _GEN = _RANDOM[/*Zero width*/ 1'b0][3:0];
        _GEN_0 = _RANDOM[/*Zero width*/ 1'b0][5:4];
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  spi_top_apb _GEN_11 (
    .clock       (clock),
    .reset       (reset),
    .in_psel     (_GEN_1),
    .in_penable  (_GEN_10 | _GEN_1),
    .in_pwrite   (_GEN_3 ? auto_apply_in_pwrite : _GEN != 4'h8),
    .in_paddr
      ({27'h0,
        _GEN_9
          ? 3'h0
          : _GEN_8
              ? 3'h4
              : _GEN_7
                  ? 3'h6
                  : _GEN_6
                      ? 3'h5
                      : _GEN_5 ? 3'h1 : _GEN_4 ? 3'h0 : auto_apply_in_paddr[4:2],
        2'h0}),
    .in_pprot    (3'h1),
    .in_pwdata
      (_GEN_8
         ? 32'h3540
         : _GEN_7
             ? 32'h1
             : _GEN_6
                 ? 32'h0
                 : _GEN_5
                     ? {8'h3, auto_apply_in_paddr[23:2], 2'h0}
                     : _GEN_4 ? 32'h0 : auto_apply_in_pwdata),
    .in_pstrb    (_GEN_3 ? auto_apply_in_pstrb : 4'hF),
    .in_pready   (__in_pready),
    .in_pslverr  (/* unused */),
    .in_prdata   (__in_prdata),
    .spi_sck     (extra_sck),
    .spi_ss      (__spi_ss),
    .spi_mosi    (extra_mosi),
    .spi_miso    (extra_miso),
    .spi_irq_out (__spi_irq_out)
  );
  assign auto_apply_in_pready = (_GEN_3 | _GEN_9) & _GEN_2;
  assign auto_apply_in_prdata =
    _GEN_9
      ? {__in_prdata[7:0], __in_prdata[15:8], __in_prdata[23:16], __in_prdata[31:24]}
      : __in_prdata;
  assign auto_apply_in_pslverr = 1'b0;
  assign extra_ss = __spi_ss[0];
endmodule

module RCU(
  input         clock,
                reset,
                io_apb4_psel,
                io_apb4_penable,
                io_apb4_pwrite,
  input  [31:0] io_apb4_paddr,
                io_apb4_pwdata,
  input  [3:0]  io_apb4_pstrb,
  output        io_apb4_pready,
  output [31:0] io_apb4_prdata,
  output        io_rcu_cpuReset,
  output [4:0]  io_rcu_cpuSel
);

  reg         canWrite;
  reg  [4:0]  cpuSelReg;
  reg         pllBypassReg;
  reg  [31:0] addrReg;
  reg         io_apb4_pready_REG;
  wire        _GEN = io_apb4_psel & ~io_apb4_penable & io_apb4_pwrite & canWrite;
  wire        _GEN_0 = io_apb4_paddr[3:2] == 2'h0;
  wire        _GEN_1 = io_apb4_pstrb[0] & io_apb4_pwdata[0];
  wire        _GEN_2 = io_apb4_paddr[3:2] == 2'h1;
  wire [4:0]  _GEN_3 = {5{io_apb4_pstrb[0]}};
  always @(posedge clock) begin
    if (reset) begin
      canWrite <= 1'h1;
      cpuSelReg <= 5'h0;
      pllBypassReg <= 1'h1;
    end
    else begin
      if (_GEN & _GEN_0)
        canWrite <= _GEN_1 | ~(io_apb4_pstrb[0]) & canWrite;
      if (~_GEN | _GEN_0 | ~_GEN_2) begin
      end
      else
        cpuSelReg <= _GEN_3 & io_apb4_pwdata[4:0] | ~_GEN_3 & cpuSelReg;
      if (~_GEN | _GEN_0 | _GEN_2 | io_apb4_paddr[3:2] != 2'h2) begin
      end
      else
        pllBypassReg <= _GEN_1 | ~(io_apb4_pstrb[0]) & pllBypassReg;
    end
    addrReg <= io_apb4_paddr;
    io_apb4_pready_REG <= io_apb4_psel;
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:1];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [1:0] i = 2'h0; i < 2'h2; i += 2'h1) begin
          _RANDOM[i[0]] = `RANDOM;
        end
        canWrite = _RANDOM[1'h0][0];
        cpuSelReg = _RANDOM[1'h0][5:1];
        pllBypassReg = _RANDOM[1'h0][6];
        addrReg = {_RANDOM[1'h0][31:7], _RANDOM[1'h1][6:0]};
        io_apb4_pready_REG = _RANDOM[1'h1][7];
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_apb4_pready = io_apb4_pready_REG;
  assign io_apb4_prdata =
    {27'h0,
     addrReg[3:2] == 2'h2
       ? {4'h0, pllBypassReg}
       : addrReg[3:2] == 2'h1 ? cpuSelReg : {4'h0, addrReg[3:2] == 2'h0 & canWrite}};
  assign io_rcu_cpuReset = canWrite;
  assign io_rcu_cpuSel = cpuSelReg;
endmodule

