module SimTop(
  input        clock,
               reset,
               rcuEn,
  input  [4:0] coreSel,
  input        externalPins_uart0_rx,
  output       externalPins_uart0_tx,
  input        externalPins_uart1_uart_rx_i,
  output       externalPins_uart1_uart_tx_o
);

  wire       _flash_miso;
  wire       _asic_spi_sck;
  wire       _asic_spi_ss;
  wire       _asic_spi_mosi;
  wire       _asic_psram_sck_o;
  wire [2:0] _asic_psram_nss_o;
  wire       _psram_dio_0_wire;
  wire       _psram_dio_1_wire;
  wire       _psram_dio_2_wire;
  wire       _psram_dio_3_wire;
  wire       _gpio0_0_wire;
  wire       _gpio0_1_wire;
  wire       _gpio0_2_wire;
  wire       _gpio0_3_wire;
  wire       _i2c_scl_0_wire;
  wire       _i2c_sda_0_wire;
  wire       _qspi_dio_0_wire;
  wire       _qspi_dio_1_wire;
  wire       _qspi_dio_2_wire;
  wire       _qspi_dio_3_wire;
  asicTopYSYXstageDE asic (
    .clock_pad_i     (clock),
    .clock_pad_o     (/* unused */),
    .resetn_pad_i    (~reset),
    .coreSel         (coreSel),
    .rcuEn           (rcuEn),
    .pll_en_i        (1'h0),
    .clk_cfg_i       (1'h0),
    .uart0_rx        (externalPins_uart0_rx),
    .uart0_tx        (externalPins_uart0_tx),
    .spi_sck         (_asic_spi_sck),
    .spi_ss          (_asic_spi_ss),
    .spi_mosi        (_asic_spi_mosi),
    .spi_miso        (_flash_miso),
    .psram_sck_o     (_asic_psram_sck_o),
    .psram_nss_o     (_asic_psram_nss_o),
    .psram_dio_0     (_psram_dio_0_wire),
    .psram_dio_1     (_psram_dio_1_wire),
    .psram_dio_2     (_psram_dio_2_wire),
    .psram_dio_3     (_psram_dio_3_wire),
    .gpio0_0         (_gpio0_0_wire),
    .gpio0_1         (_gpio0_1_wire),
    .gpio0_2         (_gpio0_2_wire),
    .gpio0_3         (_gpio0_3_wire),
    .uart1_uart_rx_i (externalPins_uart1_uart_rx_i),
    .uart1_uart_tx_o (externalPins_uart1_uart_tx_o),
    .i2c_scl_0       (_i2c_scl_0_wire),
    .i2c_sda_0       (_i2c_sda_0_wire),
    .pwm0_pwm_o      (/* unused */),
    .qspi_sck_o      (/* unused */),
    .qspi_nss_o      (/* unused */),
    .qspi_dio_0      (_qspi_dio_0_wire),
    .qspi_dio_1      (_qspi_dio_1_wire),
    .qspi_dio_2      (_qspi_dio_2_wire),
    .qspi_dio_3      (_qspi_dio_3_wire)
  );
  flash flash (
    .sck  (_asic_spi_sck),
    .ss   (_asic_spi_ss),
    .mosi (_asic_spi_mosi),
    .miso (_flash_miso)
  );
  ESPWrapper #(
    .nss(4)
  ) espPsram (
    .sck_o (_asic_psram_sck_o),
    .nss_o ({1'h0, _asic_psram_nss_o}),
    .dio_0 (_psram_dio_0_wire),
    .dio_1 (_psram_dio_1_wire),
    .dio_2 (_psram_dio_2_wire),
    .dio_3 (_psram_dio_3_wire)
  );
endmodule

module ElaborateTop(
  input clock,
        reset
);

  SimTop dut (
    .clock                        (clock),
    .reset                        (reset),
    .rcuEn                        (1'h0),
    .coreSel                      (5'h0),
    .externalPins_uart0_rx        (1'h0),
    .externalPins_uart0_tx        (/* unused */),
    .externalPins_uart1_uart_rx_i (1'h0),
    .externalPins_uart1_uart_tx_o (/* unused */)
  );
endmodule


// ----- 8< ----- FILE "./ESPWrapper.v" ----- 8< -----

module ESPWrapper #(
  parameter nss = 4
)(
  input sck_o,
  input [nss-1:0] nss_o,
  inout dio_0,
  inout dio_1,
  inout dio_2,
  inout dio_3
);
  ESP_PSRAM64H psram(
   .sclk(sck_o),
   .csn(nss_o[0]),
   .sio({dio_3, dio_2, dio_1, dio_0})  // bidirection for inout
 );
endmodule
    
